def generate(seed):
    r = random.Random(seed)
    n = r.randint(5, 7)
    pts = []
    while len(pts) < n:
        p = (r.randint(0, 9), r.randint(0, 9))
        if p not in pts:
            pts.append(p)
    best = None
    for per in itertools.permutations(range(1, n)):
        t = (0,) + per
        d = sum(abs(pts[t[i]][0] - pts[t[i - 1]][0]) + abs(pts[t[i]][1] - pts[t[i - 1]][1])
                for i in range(n))
        if best is None or d < best:
            best = d
    b = best + r.choice([0, 0, 1, 2])
    return ' '.join('%d,%d' % p for p in pts) + '|' + str(b)

