def solve(clue):
    p, b = clue.split('|')
    pts = [tuple(int(v) for v in q.split(',')) for q in p.split()]
    b = int(b)
    n = len(pts)
    best, bd = None, None
    for per in itertools.permutations(range(1, n)):
        t = (0,) + per
        d = sum(abs(pts[t[i]][0] - pts[t[i - 1]][0]) + abs(pts[t[i]][1] - pts[t[i - 1]][1])
                for i in range(n))
        if bd is None or d < bd:
            bd, best = d, t
        if d <= b:
            return ' '.join(str(i) for i in t)
    return ' '.join(str(i) for i in best)

